import subprocess, tempfile, os, re
def fisher(a_intervals, b_intervals, genome_lines):
    td = tempfile.mkdtemp()
    a_path = os.path.join(td,"a.bed")
    b_path = os.path.join(td,"b.bed")
    g_path = os.path.join(td,"g.txt")
    with open(a_path,'w') as f:
        for c,s,e in a_intervals:
            f.write(f"{c}\t{s}\t{e}\n")
    with open(b_path,'w') as f:
        for c,s,e in b_intervals:
            f.write(f"{c}\t{s}\t{e}\n")
    with open(g_path,'w') as f:
        for l in genome_lines:
            f.write(l+"\n")
    out = subprocess.run(f"./executable fisher -a {a_path} -b {b_path} -g {g_path}", shell=True, stdout=subprocess.PIPE).stdout.decode()
    m=re.search(r"Number of possible intervals.*:\s*(\d+)", out)
    return int(m.group(1)) if m else None

def make_intervals(n, L, offset):
    iv=[]
    for i in range(n):
        iv.append(("chr1", offset+i*(L+10), offset+i*(L+10)+L))
    return iv

for L in [50,10,20,5]:
    for nA in [1,2,4]:
        for nB in [1,2]:
            a = make_intervals(nA, L, 0)
            b = make_intervals(nB, L, 500)
