    --contact     Feature requests, bugs, mailing lists, etc.

"""
CONTACT = """
- For further help, or to report a bug, please 
  email the bedtools mailing list: 
     bedtools-discuss@googlegroups.com

- The development repository can be found at: 
     https://github.com/arq5x/bedtools

- Stable releases of bedtools can be found at: 
     https://github.com/arq5x/bedtools2/releases

"""
# help texts will be loaded from file if present else fallback
import json, pathlib
_HELP_JSON = pathlib.Path(__file__).with_name("help_texts.json")
if _HELP_JSON.exists():
    import json
    _data=json.loads(_HELP_JSON.read_text())
    HELP_TEXTS=_data.get("help_texts",{})
else:
    # embedded minimal fallback - will be replaced by compile step
    HELP_TEXTS={}

# For fallback if not loaded, try to load from captured file /tmp/full_help.json if exists (for testing)
if not HELP_TEXTS and pathlib.Path("/tmp/full_help.json").exists():
    import json
    _data=json.loads(pathlib.Path("/tmp/full_help.json").read_text())
    HELP_TEXTS=_data.get("help_texts",{})

# Ensure HELP_TEXTS populated for known tools even if missing, use generic
for _cmd in ["intersect","window","closest","coverage","map","genomecov","merge","cluster","complement","shift","subtract","slop","flank","sort","random","shuffle","sample","spacing","annotate","multiinter","unionbedg","pairtobed","pairtopair","bamtobed","bedtobam","bamtofastq","bedpetobam","bed12tobed6","getfasta","maskfasta","nuc","multicov","tag","jaccard","reldist","fisher","overlap","igv","links","makewindows","groupby","expand","split","summary"]:
    if _cmd not in HELP_TEXTS:
        HELP_TEXTS[_cmd]=f"\nTool:    bedtools {_cmd}\nVersion: 7057f85\nSummary: ...\n\nUsage:   bedtools {_cmd} [OPTIONS]\n\n"

def eprint(*args, **kwargs):
    print(*args, file=sys.stderr, **kwargs)

