def is_header_line(line):
    s=line.lstrip()
    return s.startswith('#') or s.startswith('browser') or s.startswith('track')

def open_input(path):
    # handle stdin, -, gzip
    if path in ("stdin", "-"):
        return sys.stdin
    if path.endswith(".gz"):
        try:
            return gzip.open(path, 'rt')
        except:
            # fallback
            return open(path, 'r')
    else:
        return open(path, 'r')

def read_bed_file(path):
    headers=[]
    records=[]
    # handle stdin specially: if path is stdin/- we read from sys.stdin
    if path in ("stdin","-"):
        f = sys.stdin
        # need to read all lines from stdin (already)
        # But sys.stdin may be tty?
