                headers.append(line)
                continue
            # split
            if '\t' in line:
                fields = line.rstrip('\n').split('\t')
            else:
                fields = line.rstrip('\n').split()
            if len(fields) < 3:
                continue
            try:
                chrom=fields[0]
                start=int(fields[1])
                end=int(fields[2])
            except:
                continue
            records.append({"chrom":chrom,"start":start,"end":end,"fields":fields,"line":line.rstrip('\n')})
        return headers, records
    else:
        # file path
        # support wildcard already expanded before
        # check existence
        if not os.path.exists(path):
            eprint(f"Error: Unable to open file {path}. Exiting.")
            sys.exit(1)
        try:
            if path.endswith(".gz"):
                fh=gzip.open(path,'rt')
            else:
                fh=open(path,'r')
        except Exception as e:
            eprint(f"Error: Unable to open file {path}. Exiting.")
            sys.exit(1)
        for line in fh:
            line=line.rstrip('\n')
            if line.strip()=="":
                continue
            if is_header_line(line):
                headers.append(line)
                continue
            if '\t' in line:
                fields=line.split('\t')
            else:
                fields=line.split()
            if len(fields) < 3:
                continue
            try:
                chrom=fields[0]
                start=int(fields[1])
                end=int(fields[2])
            except:
                continue
            records.append({"chrom":chrom,"start":start,"end":end,"fields":fields,"line":line})
        fh.close()
        return headers, records

def read_genome(path):
    # returns dict chrom->size, order list
    if not os.path.exists(path):
        eprint(f"Error: Unable to open file {path}. Exiting.")
        sys.exit(1)
    order=[]
    sizes={}
    # handle gz?
    if path.endswith(".gz"):
        fh=gzip.open(path,'rt')
    else:
        fh=open(path,'r')
    for line in fh:
        line=line.strip()
        if not line or line.startswith('#'):
            continue
        parts=line.split()
        if len(parts)<2:
            continue
        chrom=parts[0]
        try:
            size=int(parts[1])
        except:
            continue
        sizes[chrom]=size
        if chrom not in order:
            order.append(chrom)
    fh.close()
    return sizes, order

def is_sorted_records(records, genome_order=None):
    # check sorted by chrom then start
    if genome_order is not None:
        # build index map
        idx={c:i for i,c in enumerate(genome_order)}
        prev_chrom=None
        prev_start=None
        prev_idx=-1
        for r in records:
            c=r["chrom"]
            s=r["start"]
            cur_idx=idx.get(c, 10**9)
            if prev_chrom is None:
                prev_chrom=c
                prev_start=s
                prev_idx=cur_idx
                continue
            if cur_idx < prev_idx:
                return False, r["line"]
            if cur_idx == prev_idx and s < prev_start:
                return False, r["line"]
            prev_idx=cur_idx
            prev_chrom=c
            prev_start=s
        return True, None
    else:
        prev_chrom=None
        prev_start=None
        for r in records:
            c=r["chrom"]
            s=r["start"]
            if prev_chrom is None:
                prev_chrom=c
                prev_start=s
                continue
            if c < prev_chrom:
                return False, r["line"]
            if c == prev_chrom and s < prev_start:
                return False, r["line"]
            prev_chrom=c
            prev_start=s
        return True, None

def overlap_len(a,b):
    if a["chrom"] != b["chrom"]:
        return 0
    return max(0, min(a["end"], b["end"]) - max(a["start"], b["start"]))

def passes_fraction(a,b,overlap, f_thr=None, F_thr=None, has_f=False, has_F=False, use_r=False, use_e=False):
    if overlap <=0:
        return False
    # if no thresholds, passes
    if not has_f and not has_F:
        return True
    len_a = a["end"]-a["start"]
    len_b = b["end"]-b["start"]
    if len_a==0 or len_b==0:
        return False
    frac_a = overlap/len_a if len_a else 0
    frac_b = overlap/len_b if len_b else 0
    if use_r:
        # require both >= f_thr
        return frac_a >= f_thr - 1e-12 and frac_b >= f_thr - 1e-12
    else:
        if has_f and has_F:
            if use_e:
                return frac_a >= f_thr - 1e-12 or frac_b >= F_thr - 1e-12
            else:
                return frac_a >= f_thr - 1e-12 and frac_b >= F_thr - 1e-12
        elif has_f:
            return frac_a >= f_thr - 1e-12
        elif has_F:
            return frac_b >= F_thr - 1e-12
        else:
            return True

def pass_strand(a,b, flag_s, flag_S):
    if not flag_s and not flag_S:
        return True
    # determine strand: field 5 (0-indexed 5) if exists else '.'
    def get_strand(rec):
        if len(rec["fields"]) >=6:
            return rec["fields"][5]
        return "."
    sa=get_strand(a)
    sb=get_strand(b)
