        # For now, require sa==sb
    if flag_S:
        return sa != sb
    return True

def get_null_b(num_fields):
    # generate null B as per bedtools
    if num_fields <=0:
        num_fields=3
    if num_fields <3:
        num_fields=3
    null=[]
    null.append(".")
    null.append("-1")
    null.append("-1")
    if num_fields >=4:
        null.append(".")
    if num_fields >=5:
        null.append("-1")
    if num_fields >=6:
        null.append(".")
    for i in range(6, num_fields):
        null.append(".")
    # trim or extend to exactly num_fields
    if len(null) > num_fields:
        null=null[:num_fields]
    elif len(null) < num_fields:
        null.extend(["."]*(num_fields-len(null)))
    return null

