            med=(vals[n//2-1]+vals[n//2])/2
        return fmt(med)
    elif op=="mode":
        c=Counter(values)
        return c.most_common(1)[0][0] if c else "."
    elif op=="antimode":
        c=Counter(values)
        if not c: return "."
        least=min(c.items(), key=lambda x: (x[1], x[0]))
        return least[0]
    elif op=="stdev":
        vals=[float(v) for v in values if is_number(v)]
        if len(vals)<2: return "0"
        mean=sum(vals)/len(vals)
        var=sum((x-mean)**2 for x in vals)/len(vals)
        return fmt(math.sqrt(var))
    elif op=="sstdev":
        vals=[float(v) for v in values if is_number(v)]
        if len(vals)<2: return "0"
        mean=sum(vals)/len(vals)
        var=sum((x-mean)**2 for x in vals)/(len(vals)-1) if len(vals)>1 else 0
        return fmt(math.sqrt(var))
    elif op=="collapse":
        return delim.join(values)
    elif op=="distinct":
        seen=set(); out=[]
        for v in values:
            if v not in seen:
                seen.add(v); out.append(v)
        return delim.join(out)
    elif op in ("distinct_sort_num","distinct_sort_num_desc"):
        vals=[]
        for v in values:
            try: vals.append(float(v))
            except: pass
        uniq=sorted(set(vals), reverse=(op=="distinct_sort_num_desc"))
        return delim.join(fmt(x) for x in uniq)
    elif op=="distinct_only":
        c=Counter(values)
        out=[k for k,v in c.items() if v==1]
        return delim.join(out)
    elif op=="count":
        return str(len(values))
    elif op=="count_distinct":
        return str(len(set(values)))
    elif op=="first":
        return values[0] if values else "."
    elif op=="last":
        return values[-1] if values else "."
    else:
        return delim.join(values)

